package main

import (
        "fmt"
        "os"
        "strings"
)

const version = "0.1.0"

func main() {
        if len(os.Args) < 2 {
                printUsage()
                os.Exit(1)
        }

        command := os.Args[1]
        args := os.Args[2:]

        switch command {
        case "list":
                cmdList(args)
        case "info":
                cmdInfo(args)
        case "register":
                cmdRegister(args)
        case "remove":
                cmdRemove(args)
        case "run":
                cmdRun(args)
        case "validate":
                cmdValidate(args)
        case "export":
                cmdExport(args)
        case "version":
                fmt.Printf("mlpipe version %s\n", version)
        case "help":
                printUsage()
        default:
                fmt.Fprintf(os.Stderr, "unknown command: %s\n", command)
                printUsage()
                os.Exit(1)
        }
}

func printUsage() {
        usage := `mlpipe - ML Inference Pipeline Manager

Usage: mlpipe <command> [arguments]

Commands:
  list                          List all registered models
  info <model>                  Show model details
  register <name> <path>        Register a model from directory
  remove <name>                 Remove a model from registry
  run <model> [options]         Run inference
  validate <model>              Validate model integrity
  export <model> --output <dir> Export model to directory
  version                       Show version
  help                          Show this help

Run Options:
  --input <file>    Input CSV file (required)
  --output <file>   Output file (default: stdout)
  --format <fmt>    Output format: csv or json (default: csv)
`
        fmt.Print(usage)
}

func parseFlags(args []string) map[string]string {
        flags := make(map[string]string)
        for i := 0; i < len(args); i++ {
                if strings.HasPrefix(args[i], "--") {
                        key := strings.TrimPrefix(args[i], "--")
                        if i+1 < len(args) && !strings.HasPrefix(args[i+1], "--") {
                                flags[key] = args[i+1]
                                i++
                        } else {
                                flags[key] = "true"
                        }
                }
        }
        return flags
}
