func findEntry(entries []RegistryEntry, name string) *RegistryEntry {
        for i := range entries {
                if entries[i].Name == name {
                        return &entries[i]
                }
        }
        return nil
}

func cmdList(args []string) {
        entries, err := loadRegistry()
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }
        if len(entries) == 0 {
                fmt.Println("No models registered.")
                return
        }
        fmt.Printf("%-20s %-10s %-8s %s\n", "NAME", "TYPE", "VERSION", "CREATED")
        for _, e := range entries {
                fmt.Printf("%-20s %-10s %-8d %s\n", e.Name, e.Type, e.Version, e.Created)
        }
}

func cmdInfo(args []string) {
        if len(args) < 1 {
                fmt.Fprintf(os.Stderr, "usage: mlpipe info <model>\n")
                os.Exit(1)
        }
        name := args[0]
        entries, err := loadRegistry()
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }
        entry := findEntry(entries, name)
        if entry == nil {
                fmt.Fprintf(os.Stderr, "error: model '%s' not found\n", name)
                os.Exit(1)
        }

        meta, err := loadModelMeta(entry.Path)
        if err != nil {
                fmt.Fprintf(os.Stderr, "error loading metadata: %v\n", err)
                os.Exit(1)
        }

        fmt.Printf("Name:        %s\n", meta["name"])
        fmt.Printf("Type:        %s\n", meta["type"])
        fmt.Printf("Version:     %s\n", meta["version"])
        fmt.Printf("Created:     %s\n", meta["created"])
        fmt.Printf("Description: %s\n", meta["description"])
        fmt.Printf("Features:    %s\n", meta["features"])
        fmt.Printf("Outputs:     %s\n", meta["outputs"])
        fmt.Printf("Path:        %s\n", entry.Path)
}

func cmdRegister(args []string) {
        if len(args) < 2 {
                fmt.Fprintf(os.Stderr, "usage: mlpipe register <name> <path>\n")
                os.Exit(1)
        }
        name := args[0]
        modelPath := args[1]

        absPath, err := filepath.Abs(modelPath)
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }

        if _, err := os.Stat(filepath.Join(absPath, "model.meta")); err != nil {
                fmt.Fprintf(os.Stderr, "error: no model.meta found at %s\n", absPath)
                os.Exit(1)
        }

        meta, err := loadModelMeta(absPath)
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }

        entries, err := loadRegistry()
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }

        if findEntry(entries, name) != nil {
                fmt.Fprintf(os.Stderr, "error: model '%s' already registered\n", name)
                os.Exit(1)
        }

        modelType := meta["type"]
        if modelType == "" {
                modelType = "unknown"
        }

        entries = append(entries, RegistryEntry{
                Name:    name,
                Path:    absPath,
                Type:    modelType,
                Version: 1,
                Created: time.Now().Format("2006-01-02"),
        })

        if err := saveRegistry(entries); err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }
        fmt.Printf("Model '%s' registered successfully.\n", name)
}

func cmdRemove(args []string) {
        if len(args) < 1 {
                fmt.Fprintf(os.Stderr, "usage: mlpipe remove <name>\n")
                os.Exit(1)
        }
        name := args[0]

        entries, err := loadRegistry()
        if err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }

        found := false
        var newEntries []RegistryEntry
        for _, e := range entries {
                if e.Name == name {
                        found = true
                } else {
                        newEntries = append(newEntries, e)
                }
        }

        if !found {
                fmt.Fprintf(os.Stderr, "error: model '%s' not found\n", name)
                os.Exit(1)
        }

        if err := saveRegistry(newEntries); err != nil {
                fmt.Fprintf(os.Stderr, "error: %v\n", err)
                os.Exit(1)
        }
        fmt.Printf("Model '%s' removed.\n", name)
}
