func runInference(inputs [][]float64, weights *WeightsData, cfg *PipelineConfig) [][]float64 {
        processed := preprocess(inputs, cfg)

        results := make([][]float64, len(processed))
        for i, row := range processed {
                output := make([]float64, weights.NumOutputs)
                for o := uint32(0); o < weights.NumOutputs; o++ {
                        sum := weights.Bias[o]
                        for f := uint32(0); f < weights.NumFeatures; f++ {
                                if int(f) < len(row) {
                                        sum += row[f] * weights.Weights[o*weights.NumFeatures+f]
                                }
                        }
                        output[o] = sum
                }
                results[i] = output
        }

