}

func preprocess(inputs [][]float64, cfg *PipelineConfig) [][]float64 {
        result := make([][]float64, len(inputs))
        for i, row := range inputs {
                result[i] = make([]float64, len(row))
                copy(result[i], row)
        }

        for i, row := range result {
                for j, val := range row {
                        if math.IsNaN(val) {
                                switch cfg.MissingStrategy {
                                case "zero":
                                        result[i][j] = 0.0
                                case "mean":
                                        result[i][j] = computeColumnMean(inputs, j)
                                }
                        }
                }
        }

        if cfg.Normalize {
                for j := 0; j < len(result[0]); j++ {
