}

func postprocess(results [][]float64, cfg *PipelineConfig) [][]float64 {
        for i, row := range results {
                for j, val := range row {
                        val = math.Max(val, cfg.ClipMin)
                        val = math.Min(val, cfg.ClipMax)
                        results[i][j] = roundToDigits(val, cfg.RoundDigits)
                }
        }
        return results
}

func computeColumnMean(data [][]float64, col int) float64 {
        sum := 0.0
        count := 0
        for _, row := range data {
                if col < len(row) && !math.IsNaN(row[col]) {
                        sum += row[col]
                        count++
                }
        }
        if count == 0 {
                return 0.0
        }
        return sum / float64(count)
}

func columnMinMax(data [][]float64, col int) (float64, float64) {
        minVal := math.Inf(1)
        maxVal := math.Inf(-1)
        for _, row := range data {
