func cmdDiff(args []string) {
	if len(args) < 2 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe diff <model1> <model2> --input <file>\n")
		os.Exit(1)
	}

	model1 := args[0]
	model2 := args[1]
	flags := parseFlags(args[2:])

	input := flags["input"]
	if input == "" {
		fmt.Fprintf(os.Stderr, "error: --input is required\n")
		os.Exit(1)
	}

	entry1, err := resolveModel(model1)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	entry2, err := resolveModel(model2)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	w1, cfg1, err := loadModelArtifacts(entry1.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading model '%s': %v\n", model1, err)
		os.Exit(1)
	}

	w2, cfg2, err := loadModelArtifacts(entry2.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading model '%s': %v\n", model2, err)
		os.Exit(1)
	}

	if w1.NumFeatures != w2.NumFeatures {
		fmt.Fprintf(os.Stderr, "error: models have different input feature counts: %s=%d, %s=%d\n", model1, w1.NumFeatures, model2, w2.NumFeatures)
		os.Exit(1)
	}

	inputs, err := readInputCSV(input)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error reading input: %v\n", err)
		os.Exit(1)
	}

	if err := validateFeatureCount(inputs, int(w1.NumFeatures)); err != nil {
		fmt.Fprintf(os.Stderr, "error: input feature count mismatch: %v\n", err)
		os.Exit(1)
	}

	r1 := runInference(inputs, w1, cfg1)
	r2 := runInference(inputs, w2, cfg2)

	maxOut := minInt(int(w1.NumOutputs), int(w2.NumOutputs))
	if int(w1.NumOutputs) != int(w2.NumOutputs) {
		fmt.Printf("note: model output dimension mismatch: %s=%d, %s=%d; comparing %d output(s)\n", model1, w1.NumOutputs, model2, w2.NumOutputs, maxOut)
	}

	var sumAbs, sumSq, maxAbs float64
	count := 0
	for i := 0; i < len(r1) && i < len(r2); i++ {
		diffs := make([]float64, maxOut)
		for o := 0; o < maxOut; o++ {
			d := math.Abs(r1[i][o] - r2[i][o])
			diffs[o] = d
			sumAbs += d
			sumSq += d * d
			if d > maxAbs {
				maxAbs = d
			}
			count++
		}
		fmt.Printf("row %d: %v\n", i, diffs)
	}

	var mae, rmse float64
	if count > 0 {
		mae = sumAbs / float64(count)
		rmse = math.Sqrt(sumSq / float64(count))
	}

	fmt.Printf("MAE: %.4f\n", mae)
	fmt.Printf("RMSE: %.4f\n", rmse)
	fmt.Printf("Max Abs Error: %.4f\n", maxAbs)
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func cmdBatch(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe batch <model> --dir <input_dir> --output-dir <output_dir> [--format csv|json]\n")
		os.Exit(1)
	}

	model := args[0]
	flags := parseFlags(args[1:])

	inputDir := flags["dir"]
	outputDir := flags["output-dir"]
	format := flags["format"]
	if format == "" {
		format = "csv"
	}
	if format != "csv" && format != "json" {
		fmt.Fprintf(os.Stderr, "error: unsupported format '%s', use 'csv' or 'json'\n", format)
		os.Exit(1)
	}
	if inputDir == "" {
		fmt.Fprintf(os.Stderr, "error: --dir is required\n")
		os.Exit(1)
	}
	if outputDir == "" {
		fmt.Fprintf(os.Stderr, "error: --output-dir is required\n")
		os.Exit(1)
	}

	entry, err := resolveModel(model)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	weights, cfg, err := loadModelArtifacts(entry.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading model: %v\n", err)
		os.Exit(1)
	}

	if err := os.MkdirAll(outputDir, 0755); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	dirEntries, err := os.ReadDir(inputDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	var files []string
	for _, de := range dirEntries {
		if de.IsDir() {
			continue
		}
		name := de.Name()
		if strings.HasSuffix(strings.ToLower(name), ".csv") {
			files = append(files, filepath.Join(inputDir, name))
		}
	}
	sort.Strings(files)

	totalFiles := len(files)
	totalRows := 0
	processed := 0
	var failures []string

