		if err != nil {
			failures = append(failures, fmt.Sprintf("%s: %v", filepath.Base(file), err))
			continue
		}

		if err := validateFeatureCount(inputs, int(weights.NumFeatures)); err != nil {
			failures = append(failures, fmt.Sprintf("%s: %v", filepath.Base(file), err))
			continue
		}

		results := runInference(inputs, weights, cfg)

		base := strings.TrimSuffix(filepath.Base(file), filepath.Ext(file))
		outPath := filepath.Join(outputDir, base+"."+format)
		f, err := os.Create(outPath)
		if err != nil {
			failures = append(failures, fmt.Sprintf("%s: %v", filepath.Base(file), err))
			continue
		}
		writeOutput(f, results, format)
		f.Close()

		processed++
		totalRows += len(results)
	}

	fmt.Printf("Batch summary:\n")
	fmt.Printf("  total files processed: %d\n", totalFiles)
	fmt.Printf("  successful: %d\n", processed)
	fmt.Printf("  total rows: %d\n", totalRows)
	fmt.Printf("  failed files: %d\n", len(failures))
	for _, fail := range failures {
		fmt.Printf("  - %s\n", fail)
	}
}
